<?php
declare(strict_types=1);

function sow_document_html(array $data): string
{
    $v = static fn(string $key, string $fallback = ''): string => e(trim((string)($data[$key] ?? $fallback)));
    $raw = static fn(string $key, string $fallback = ''): string => trim((string)($data[$key] ?? $fallback));
    $selected = array_map('intval', is_array($data['selected_sections'] ?? null) ? $data['selected_sections'] : range(1, 48));
    $show = static fn(int $number): bool => in_array($number, $selected, true);
    $items = static fn(string $value): array => array_values(array_filter(array_map('trim', preg_split('/\R/u', $value) ?: [])));
    $rows = static function (string $value, int $columns): array {
        $result = [];
        foreach (preg_split('/\R/u', $value) ?: [] as $line) {
            if (trim($line) === '') continue;
            $result[] = array_pad(array_slice(array_map('trim', explode('|', $line)), 0, $columns), $columns, '—');
        }
        return $result;
    };
    $list = static function (array $values): void { if (!$values) return; echo '<ul>'; foreach ($values as $value) echo '<li>'.e($value).'</li>'; echo '</ul>'; };
    $table = static function (array $headers, array $values): void { if (!$values) return; echo '<table><thead><tr>'; foreach ($headers as $header) echo '<th>'.e($header).'</th>'; echo '</tr></thead><tbody>'; foreach ($values as $row) { echo '<tr>'; foreach ($row as $cell) echo '<td>'.e($cell).'</td>'; echo '</tr>'; } echo '</tbody></table>'; };
    $section = static function (int $number, string $title, callable $content) use ($show): void { if (!$show($number)) return; echo '<section class="sow-section"><h2>'.$number.'. '.e($title).'</h2>'; $content(); echo '</section>'; };
    ob_start();
    ?>
